import { StrategyReminderSession } from "../../../src/memory/learning-strategy-reminders.ts";
import { DIAGNOSTIC_FACTS, observeDiagnosticReports } from "./diagnostic-observations.mjs";
import { PUBLIC_DEVICE_FACTS, requirePublishedSnapshot } from "./public-observations.mjs";

// Host-authored hypothesis derived from the completed development studies.
// These are not claimed to have been generated by an autonomous learner.
export const CONDITIONAL_REMINDERS = [
  {
    id: "ambiguous-data-status",
    when: [
      { fact: "device.dataUnavailable", is: true },
      { fact: "device.dataEnabled", is: "unknown" },
    ],
    text: "A status bar saying Data Disabled describes availability, not necessarily the configured switch. Ask for check_network_status before toggling mobile data. If the switch is already on, leave it on and diagnose SIM, airplane mode or signal instead.",
  },
  {
    id: "data-already-enabled",
    when: [
      { fact: "device.dataUnavailable", is: true },
      { fact: "device.dataEnabled", is: true },
    ],
    text: "The customer's explicit report says mobile data is enabled. Reuse that observation and skip toggling it. Investigate connectivity prerequisites. A setting-changing action invalidates this observation; confirm the new state afterwards.",
  },
  {
    id: "abroad-prerequisites",
    when: [
      { fact: "customer.abroad", is: true },
      { fact: "customer.dataProblem", is: true },
    ],
    unless: [
      { fact: "device.roamingEnabled", is: true },
      { fact: "account.roamingEnabled", is: true },
      { fact: "account.dataExhausted", is: false },
    ],
    text: "For a data or MMS problem abroad, distinguish account roaming, the device roaming switch and remaining data allowance. Check only prerequisites not already verified. Obtain required consent for changes, then test the requested service.",
  },
  {
    id: "observed-data-exhaustion",
    when: [
      { fact: "account.dataExhausted", is: true },
      { fact: "customer.dataProblem", is: true },
    ],
    text: "Account observations show exhausted data. Follow the policy and obtain consent before refueling; verify the updated allowance and requested service. Do not repeat an already-completed refill or substitute unrelated device changes.",
  },
];
const deviceFacts = [
  "device.dataUnavailable",
  "device.dataEnabled",
  "device.roamingEnabled",
  ...DIAGNOSTIC_FACTS,
];
const accountFacts = ["account.dataExhausted", "account.roamingEnabled"];
export const STRUCTURED_REMINDER_FACTS = [...PUBLIC_DEVICE_FACTS, ...accountFacts];
export const REMINDER_FACTS = [
  ...deviceFacts,
  ...accountFacts,
  "customer.abroad",
  "customer.dataProblem",
];

/** Intentionally narrow extraction from actor-visible evidence, with unknown as the default. */
export function createTelecomReminders(rules, { structured = false } = {}) {
  if (
    structured &&
    rules.some((rule) =>
      [...rule.when, ...(rule.unless ?? [])].some(
        (predicate) => !STRUCTURED_REMINDER_FACTS.includes(predicate.fact),
      ),
    )
  )
    throw new Error("Unsupported structured reminder fact");
  const memory = new StrategyReminderSession();
  const account = accountObservations(memory);
  const set = (key, value, evidence) => memory.observe(key, value, evidence);
  let publicScope;
  let lastReport = 0;
  const publicRevisions = new Map();
  return {
    customerObservations(snapshot) {
      requirePublishedSnapshot(snapshot);
      if (!structured) throw new Error("Structured observations require structured routing");
      const report = Number(snapshot.reportId.slice("report-".length));
      if (report <= lastReport || (publicScope !== undefined && snapshot.scope < publicScope))
        throw new Error("Out-of-order public observation snapshot");
      lastReport = report;
      if (publicScope !== snapshot.scope) {
        memory.invalidate(PUBLIC_DEVICE_FACTS);
        publicRevisions.clear();
        publicScope = snapshot.scope;
      }
      for (const fact of PUBLIC_DEVICE_FACTS) {
        const record = snapshot.records.find((item) => item.fact === fact);
        if (!record || publicRevisions.get(fact) !== record.revision) memory.invalidate([fact]);
        if (!record) {
          publicRevisions.delete(fact);
          continue;
        }
        publicRevisions.set(fact, record.revision);
        set(
          fact,
          record.value,
          `${snapshot.reportId}/${record.sourceId}/${record.fact}@${record.revision}`,
        );
      }
    },
    customerSpeech(text, evidence) {
      if (structured) return; // Prose cannot establish or override diagnostic facts.
      observeDiagnosticReports(memory, text, evidence);
      // Questions, hedging and instructions are not confirmations of a switch.
      // Exact diagnostic labels are supported; arbitrary natural language is not.
      for (const [label, key] of [
        ["Mobile Data Enabled", "device.dataEnabled"],
        ["Data Roaming Enabled", "device.roamingEnabled"],
      ]) {
        const reports = [
          ...text.matchAll(
            new RegExp(`^[ \\t*•-]*${label}\\*{0,2}\\s*:\\*{0,2}\\s*(yes|no)[ \\t*.!]*$`, "gmi"),
          ),
        ];
        if (!reports.length) continue;
        if (new Set(reports.map((m) => m[1].toLowerCase())).size === 1)
          set(key, reports[0][1].toLowerCase() === "yes", evidence);
        else memory.invalidate([key]);
      }
      if (/\bData Disabled\b/i.test(text)) set("device.dataUnavailable", true, evidence);
      if (/\bData Enabled\b/i.test(text) && !/Mobile Data Enabled\s*:/i.test(text))
        set("device.dataUnavailable", false, evidence);
      if (/\b(?:MMS|mobile data|internet|picture messages?|photo messages?)\b/i.test(text))
        set("customer.dataProblem", true, evidence);
      const travel = [];
      for (const sentence of text.match(/[^.!?\n]+[.!?]?/g) ?? []) {
        if (sentence.trim().endsWith("?")) continue;
        const clauses = sentence.split(/[,;—]/).map((part) => part.trim());
        if (/\b(?:if|maybe|might|would|tomorrow)\b/i.test(clauses[0])) continue;
        // Also accept an explicit conclusion: "I'm in France, so I'm abroad."
        // A third-person quote or conditional premise cannot establish location.
        const reports = [
          clauses[0],
          ...(/^I(?:['’]m| am)\s/i.test(clauses[0])
            ? clauses.slice(1).filter((clause) => /^so I(?:['’]m| am)\s/i.test(clause))
            : []),
        ];
        for (const clause of reports) {
          const report = clause.match(
            /^(?:so )?I(?:['’]m| am)\s+(?:(?:currently|still|now)\s+)?(not\s+|no longer\s+)?(?:abroad|travell?ing\s+(?:internationally|abroad))(?:\s+in\s+[\p{L} -]+)?[.!]?$/iu,
          );
          if (report) travel.push(!report[1]);
        }
      }
      if (new Set(travel).size > 1) memory.invalidate(["customer.abroad"]);
      else if (travel.length) set("customer.abroad", travel[0], evidence);
    },
    actorSpeech(text) {
      if (structured) return; // Snapshot freshness is checked at explicit publication.
      if (
        /\b(?:toggle|reboot|restart|reset|reseat|enable|disable|switch|turn|change|set)(?:_[a-z_]+)?\b/i.test(
          text,
        )
      )
        memory.invalidate(deviceFacts);
    },
    actorTool: account,
    take: () => memory.take(rules),
  };
}

const phoneDigits = (value) => (typeof value === "string" ? value.replace(/\D/g, "") : "");
const quantity = (value) =>
  (typeof value === "number" || (typeof value === "string" && value.trim() !== "")) &&
  Number.isFinite(Number(value)) &&
  Number(value) >= 0;

/** Join only observed, owned records for the phone actually used in the lookup. */
function accountObservations(memory) {
  let customerId, phone, selected;
  let owned = new Set();
  const lines = new Map(),
    plans = new Map(),
    usage = new Map();
  const derive = () => {
    const matches = [...lines.values()].filter(
      ({ value }) =>
        owned.has(value.line_id) &&
        (phone ? phoneDigits(value.phone_number) === phone : owned.size === 1),
    );
    const line = matches.length === 1 ? matches[0] : undefined;
    if (selected !== line?.value.line_id) {
      memory.invalidate([...deviceFacts, ...accountFacts]);
      selected = line?.value.line_id;
    }
    if (!line) {
      memory.invalidate(accountFacts);
      return;
    }
    if (typeof line.value.roaming_enabled === "boolean")
      memory.observe("account.roamingEnabled", line.value.roaming_enabled, line.evidence);
    else memory.invalidate(["account.roamingEnabled"]);
    const direct = usage.get(selected),
      plan = plans.get(line.value.plan_id);
    const values = direct
      ? [direct.value.data_used_gb, direct.value.data_limit_gb, direct.value.data_refueling_gb]
      : [line.value.data_used_gb, plan?.value.data_limit_gb, line.value.data_refueling_gb];
    if (!values.every(quantity)) {
      memory.invalidate(["account.dataExhausted"]);
      return;
    }
    const [used, limit, refuel] = values.map(Number);
    memory.observe(
      "account.dataExhausted",
      used >= limit + refuel,
      direct ? direct.evidence : `${line.evidence} + ${plan.evidence}`,
    );
  };
  return (event, evidence) => {
    if (event.error) return;
    const args = event.arguments ?? {};
    if (["refuel_data", "enable_roaming", "disable_roaming"].includes(event.name)) {
      if (args.customer_id !== customerId || !owned.has(args.line_id)) return;
      usage.delete(args.line_id);
      const line = lines.get(args.line_id);
      if (line) {
        // Keep identity for selection, but never revive pre-mutation account facts
        // when an unrelated plan/line is subsequently inspected.
        delete line.value.data_used_gb;
        delete line.value.data_refueling_gb;
        delete line.value.roaming_enabled;
      }
      if (selected === args.line_id) memory.invalidate(accountFacts);
      derive();
      return;
    }
    let value;
    try {
      value = JSON.parse(event.content);
    } catch {
      return;
    }
    if (event.name === "get_customer_by_name" && Array.isArray(value) && value.length === 1)
      [value] = value;
    if (!value || typeof value !== "object" || Array.isArray(value)) return;
    if (
      [
        "get_customer_by_phone",
        "get_customer_by_id",
        "get_customer_by_name",
        "get_details_by_id",
      ].includes(event.name) &&
      typeof value.customer_id === "string" &&
      Array.isArray(value.line_ids) &&
      value.line_ids.every((id) => typeof id === "string")
    ) {
      const nextPhone =
        event.name === "get_customer_by_phone"
          ? phoneDigits(args.phone_number)
          : customerId === value.customer_id
            ? phone
            : undefined;
      if (
        (customerId !== undefined && customerId !== value.customer_id) ||
        (phone !== undefined && nextPhone !== phone)
      ) {
        memory.reset();
        lines.clear();
        plans.clear();
        usage.clear();
        selected = undefined;
      }
      customerId = value.customer_id;
      phone = nextPhone || undefined;
      owned = new Set(value.line_ids);
      for (const id of lines.keys())
        if (!owned.has(id)) {
          lines.delete(id);
          usage.delete(id);
        }
    } else if (
      event.name === "get_details_by_id" &&
      value.line_id === args.id &&
      owned.has(value.line_id)
    ) {
      lines.set(value.line_id, { value, evidence });
      usage.delete(value.line_id);
    } else if (
      event.name === "get_details_by_id" &&
      typeof value.plan_id === "string" &&
      value.plan_id === args.id
    ) {
      plans.set(value.plan_id, { value, evidence });
      for (const [id, line] of lines) if (line.value.plan_id === value.plan_id) usage.delete(id);
    } else if (
      event.name === "get_data_usage" &&
      args.customer_id === customerId &&
      args.line_id === value.line_id &&
      owned.has(value.line_id)
    ) {
      usage.set(value.line_id, { value, evidence });
    } else return;
    derive();
  };
}
